{"sql": "
WITH adv_ncts AS (
  SELECT DISTINCT nct_id FROM population_mentions WHERE kind='disease_stage' AND term_id='ADVANCED'
)
SELECT count(DISTINCT p.asset_id) AS n_drugs, count(DISTINCT p.nct_id) as n_trials
FROM v_programs p JOIN assets a USING (asset_id)
JOIN unnest(p.nct_ids) AS t(nct_id) ON TRUE
JOIN adv_ncts an ON an.nct_id = t.nct_id
WHERE p.condition_key = 'D002289' AND NOT a.is_combo;
"}

