{"sql": "
-- combined union across both condition keys (any lung cancer / NSCLC program) - single-drug asset count
WITH nsclc AS (SELECT DISTINCT p.asset_id FROM v_programs p JOIN assets a USING(asset_id) WHERE p.condition_key='D002289' AND NOT a.is_combo),
     lung AS (SELECT DISTINCT p.asset_id FROM v_programs p JOIN assets a USING(asset_id) WHERE p.condition_key='D008175' AND NOT a.is_combo)
SELECT count(*) AS n_union FROM (SELECT asset_id FROM nsclc UNION SELECT asset_id FROM lung);
"}

